// Kukicha Standard Library - Terminal capability detection
// Single source of truth for tty status, color enablement, and terminal width.
// Other stdlib packages (color, log, spinner) should read from here instead
// of growing their own NO_COLOR / FORCE_COLOR / isatty plumbing — that's how
// we keep capability state consistent when callers redirect output or call
// SetColorEnabled in tests.
//
// Examples:
//
//	if term.IsTTY(os.Stdout) ...
//	if term.ColorEnabled() ...
//	term.SetColorEnabled(false)   # tests / known-non-tty sinks
//	cols := term.Width()
package term

import (
	"os"
	"strconv"
	"unicode/utf8"
)

var colorOverridden bool

var colorOverrideValue bool

// IsTTY reports whether f is a terminal (character device).
// Pass os.Stdout, os.Stderr, or any *os.File. Returns false for empty.
func IsTTY(f *os.File) bool {
	if f == nil {
		return false
	}
	info, err := f.Stat()
	if err != nil {
		return false
	}
	return info.Mode()&os.ModeCharDevice != 0
}

// ColorEnabledFor reports whether ANSI color should be emitted to w.
// Resolution order:
//  1. SetColorEnabled override (if called)
//  2. FORCE_COLOR env (any non-empty value enables)
//  3. NO_COLOR env (any non-empty value disables, https://no-color.org)
//  4. IsTTY(w)
//
// No caching — callers may set env vars or redirect output between calls.
func ColorEnabledFor(w *os.File) bool {
	if colorOverridden {
		return colorOverrideValue
	}
	if os.Getenv("FORCE_COLOR") != "" {
		return true
	}
	if os.Getenv("NO_COLOR") != "" {
		return false
	}
	return IsTTY(w)
}

// ColorEnabled is shorthand for ColorEnabledFor(os.Stdout).
func ColorEnabled() bool {
	return ColorEnabledFor(os.Stdout)
}

// SetColorEnabled forces color on or off, overriding env vars and tty detection.
// Affects every stdlib package that reads from term. Call at startup or in
// test setup; concurrent writes during normal program execution aren't supported.
func SetColorEnabled(enabled bool) {
	colorOverridden = true
	colorOverrideValue = enabled
}

// ResetColorOverride clears any SetColorEnabled override, returning detection
// to env vars + tty. Mainly useful in test teardown.
func ResetColorOverride() {
	colorOverridden = false
	colorOverrideValue = false
}

// VisibleWidth returns the rendered column width of s, stripping ANSI CSI
// escape sequences (the kind emitted by stdlib/color). Counts runes, so
// multi-byte characters contribute 1 column. Wide CJK and emoji are not
// perfectly handled — for typical CLI output (ASCII + colored ANSI), this
// is the correct measurement to use for padding/alignment.
//
// Example:
//
//	term.VisibleWidth("\x1b[31mhello\x1b[0m") equals 5
func VisibleWidth(s string) int {
	width := 0
	i := 0
	n := len(s)
	for i < n {
		if s[i] == 0x1b && i+1 < n && s[i+1] == 0x5b {
			i += 2
			for i < n {
				b := int(s[i])
				i += 1
				if func() bool { _cmp_1 := 0x40; _cmp_2 := b; return _cmp_1 <= _cmp_2 && _cmp_2 <= 0x7e }() {
					break
				}
			}
			continue
		}
		_, size := utf8.DecodeRuneInString(s[i:])
		if size == 0 {
			i += 1
		} else {
			i += size
		}
		width += 1
	}
	return width
}

// PadRightVisible returns s padded with spaces on the right to at least n
// rendered columns. Uses VisibleWidth so ANSI-colored strings align with
// plain strings of equal display width.
func PadRightVisible(s string, n int) string {
	w := VisibleWidth(s)
	if w >= n {
		return s
	}
	pad := n - w
	out := s
	j := 0
	for j < pad {
		out = out + " "
		j += 1
	}
	return out
}

// PadLeftVisible returns s padded with spaces on the left to at least n
// rendered columns — right-aligned columns (counts, sizes, version numbers)
// where ANSI-colored cells must still align with plain strings. The obvious
// stdlib/table consumer for numeric columns.
func PadLeftVisible(s string, n int) string {
	w := VisibleWidth(s)
	if w >= n {
		return s
	}
	pad := n - w
	out := ""
	j := 0
	for j < pad {
		out = out + " "
		j += 1
	}
	return out + s
}

// Width returns the terminal column count, falling back to 80.
// Reads the COLUMNS environment variable. ioctl-based detection is
// intentionally omitted to keep this package dependency-free; callers that
// need live resize tracking can wrap golang.org/x/term themselves.
func Width() int {
	cols := os.Getenv("COLUMNS")
	if cols == "" {
		return 80
	}
	n, err := strconv.Atoi(cols)
	if err != nil {
		return 80
	}
	if n <= 0 {
		return 80
	}
	return n
}
